import{_ as t,o,c as r,aj as a}from"./chunks/framework.C6uXqnaX.js";const p=JSON.parse('{"title":"Suspicious URL Origin Change","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"errors/NG05703.md","filePath":"errors/NG05703.md"}'),s={name:"errors/NG05703.md"};function i(n,e,c,d,l,h){return o(),r("div",null,e[0]||(e[0]=[a('<h1 id="suspicious-url-origin-change" tabindex="-1">Suspicious URL Origin Change <a class="header-anchor" href="#suspicious-url-origin-change" aria-label="Permalink to &quot;Suspicious URL Origin Change&quot;">​</a></h1><p>This error occurs in Server-Side Rendering (SSR) environments when a URL resolution results in an unexpected origin change. This check is a security feature in <code>@angular/platform-server</code> designed to protect your application from Server-Side Request Forgery (SSRF) and security bypasses.</p><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p>To perform HTTP requests and process route states during SSR, Angular must resolve relative URLs to absolute URLs.</p><p>During this resolution process, Angular validates that the resolved URL does not unexpectedly point to an external or untrusted origin. If a URL behaves like a relative path but resolves to a different origin, Angular throws <code>NG05703</code> and blocks the request/navigation.</p><h3 id="common-causes" tabindex="-1">Common causes <a class="header-anchor" href="#common-causes" aria-label="Permalink to &quot;Common causes&quot;">​</a></h3><ul><li><strong>Backslash-prefixed hijack attempts (open redirects / SSRF bypass):</strong> Relative paths beginning with slashes and backslashes (such as <code>/\\\\attacker.com/path</code> or <code>\\\\\\\\attacker.com/path</code>) can be interpreted differently by browsers and server-side URL parsers. In some parser implementations, these resolve to an absolute URL pointing to <code>attacker.com</code>. Angular detects this mismatch and blocks the resolution.</li><li><strong>Disallowed state changes to different origins:</strong> Navigation or URL updates (e.g. using <code>location.replaceState</code> or <code>location.pushState</code>) that change the origin of the application when the environment is configured to restrict URL changes to the current origin only.</li><li><strong>SSR bootstrap URL mismatch:</strong> In server-side rendering, if the <code>url</code> passed to the renderer does not align with the base origin configured for the application (such as <code>APP_BASE_HREF</code>), the router might attempt to synchronize the location on startup, causing a disallowed origin change.</li><li><strong>Obfuscated protocol schemes:</strong> Absolute URLs with obfuscated or malformed protocols (e.g. <code>ht\\ntp://evil.com/path</code>) that attempt to bypass origin checks.</li></ul><h2 id="debugging-the-error" tabindex="-1">Debugging the error <a class="header-anchor" href="#debugging-the-error" aria-label="Permalink to &quot;Debugging the error&quot;">​</a></h2><p>Check the URL that triggered the error. Ensure it does not contain unexpected backslashes, line breaks, or other characters that could trigger parsing anomalies:</p><ul><li>Avoid using backslashes (<code>\\</code>) in relative URLs or routing paths.</li><li>Make sure any user-supplied URLs or query parameters are properly validated and sanitized before being processed in SSR.</li><li><strong>Align SSR bootstrap URL with configured base URL:</strong> If the error occurs on startup in an SSR environment, ensure that the <code>url</code> passed to the renderer matches the expected base origin/host (e.g. <code>APP_BASE_HREF</code>). Avoid using dynamic URLs from raw request headers (like <code>X-Forwarded-Host</code>) if they do not match the trusted application origin.</li><li>If you intentionally want to make requests to a different domain via a protocol-relative URL (<code>//other-domain.com/path</code>), ensure it is allowed by the configuration or use an explicit scheme (<code>http://</code> or <code>https://</code>).</li></ul>',10)]))}const g=t(s,[["render",i]]);export{p as __pageData,g as default};
